@extends('layouts.app') @section('content')<section class="section"><h1>Your Cart</h1>@php($subtotal=collect($cart)->sum(fn($i)=>$i['price']*$i['quantity'])) @if(!$cart)<p>Your cart is empty.</p><a class="btn-red" href="{{ route('collection','all') }}">SHOP NOW</a>@else<form method="post" action="{{ route('cart.update') }}">@csrf @method('PATCH')<div class="cart-list">@foreach($cart as $i)<div class="cart-item"><img src="{{ asset($i['image']) }}"><div><b>{{ $i['name'] }}</b><p>{{ $i['sku'] }}</p></div><input class="qty" type="number" name="qty[{{ $i['id'] }}]" value="{{ $i['quantity'] }}" min="0"><b>${{ number_format($i['price']*$i['quantity'],2) }}</b></div>@endforeach</div><button class="add-btn">UPDATE CART</button></form><div class="order-summary"><p>Subtotal <b>${{ number_format($subtotal,2) }}</b></p><p>Shipping <b>{{ $subtotal>=99?'FREE':'$9.99' }}</b></p><a class="cta" href="{{ route('checkout') }}">PROCEED TO CHECKOUT</a></div>@endif</section>@endsection